47	async function fetchWithRetry(url: string, pat: string, signal?: AbortSignal): Promise<Response> {
48	  let attempt = 0;
49	  while (true) {
50	    const response = await fetch(url, {
51	      headers: { Authorization: `Bearer ${pat}` },
52	      signal,
53	    });
54	
55	    if (response.status !== 429 || attempt >= MAX_RETRY_ATTEMPTS) {
56	      return response;
57	    }
58	
59	    const parsed = response.headers.get('Retry-After') ? Number.parseInt(response.headers.get('Retry-After')!, 10) : Number.NaN;
60	    const delay = Number.isFinite(parsed) && parsed > 0
61	      ? parsed * 1000
62	      : Math.min(BASE_DELAY_MS * 2 ** attempt, MAX_DELAY_MS);
63	
64	    console.log(`[konnect] Rate limited. Retrying in ${delay}ms (attempt ${attempt + 1}/${MAX_RETRY_ATTEMPTS})`);
65	    await new Promise<void>((resolve, reject) => {
66	      const timer = setTimeout(resolve, delay);
67	      signal?.addEventListener('abort', () => { clearTimeout(timer); reject(signal.reason); }, { once: true });
68	    });
69	    attempt++;
70	  }
71	}
