73	export function extractRegionFromEndpoint(endpoint: string): string {
74	  // e.g. "https://abc123.us.cp0.konghq.com" → "us"
75	  try {
76	    const hostname = new URL(endpoint).hostname;
77	    const parts = hostname.split('.');
78	    // Pattern: <id>.<region>.cp0.konghq.com
79	    if (parts.length >= 4 && parts[parts.length - 2] === 'konghq' && parts[parts.length - 1] === 'com') {
80	      if (parts[parts.length - 3] === 'cp0') {
81	        return parts[parts.length - 4];
82	      }
83	      console.warn(`[konnect] Unexpected endpoint hostname format, defaulting region to "us": ${hostname}`);
84	    }
85	  } catch {
86	    console.warn(`[konnect] Malformed control_plane_endpoint, defaulting region to "us": ${endpoint}`);
87	  }
88	  return 'us';
89	}
