106	export async function validatePat(pat: string): Promise<PatValidationResult> {
107	  try {
108	    const response = await fetch(`${getGlobalApi()}/v2/control-planes?page[size]=1`, {
109	      headers: { Authorization: `Bearer ${pat}` },
110	    });
111	    if (response.ok) {
112	      return { valid: true };
113	    }
114	    if (response.status === 401) {
115	      return { valid: false, error: 'Invalid token (401 Unauthorized).' };
116	    }
117	    if (response.status === 403) {
118	      return { valid: false, error: 'Token lacks permission to list control planes (403 Forbidden).' };
119	    }
120	    return { valid: false, error: `Konnect returned ${response.status}.` };
121	  } catch (err) {
122	    return { valid: false, error: err instanceof Error ? err.message : 'Could not reach Konnect.' };
123	  }
124	}
