126	export async function* fetchAllControlPlanes(
127	  pat: string,
128	  signal?: AbortSignal,
129	): AsyncGenerator<KonnectControlPlane[]> {
130	  let page = 1;
131	  let totalPages = 1;
132	
133	  do {
134	    const url = `${getGlobalApi()}/v2/control-planes?page[size]=${PAGE_SIZE}&page[number]=${page}`;
135	    const response = await fetchWithRetry(url, pat, signal);
136	
137	    if (!response.ok) {
138	      throw new Error(`Konnect API error ${response.status} fetching control planes`);
139	    }
140	
141	    const body = await response.json();
142	    const total: number = body?.meta?.page?.total ?? 0;
143	    totalPages = Math.ceil(total / PAGE_SIZE) || 1;
144	
145	    yield body.data as KonnectControlPlane[];
146	    page++;
147	  } while (page <= totalPages);
148	}
