150	async function fetchAllOffsetPaginated<T>(
151	  baseUrl: string,
152	  pat: string,
153	  errorContext: string,
154	  signal?: AbortSignal,
155	): Promise<T[]> {
156	  const results: T[] = [];
157	  let offset: string | null = null;
158	
159	  do {
160	    const url = offset ? `${baseUrl}?size=${PAGE_SIZE}&offset=${offset}` : `${baseUrl}?size=${PAGE_SIZE}`;
161	    const response = await fetchWithRetry(url, pat, signal);
162	
163	    if (!response.ok) {
164	      throw new Error(`Konnect API error ${response.status} ${errorContext}`);
165	    }
166	
167	    const body = await response.json();
168	    results.push(...(body.data as T[]));
169	    offset = body.offset ?? null;
170	  } while (offset !== null);
171	
172	  return results;
173	}
