87	/**
88	 * Merges Konnect-managed headers into an existing header array.
89	 * Konnect header names are stored lowercase at the API boundary, so all comparisons
90	 * here are direct string equality. Previously Konnect-managed headers that are no
91	 * longer incoming are removed using the persisted `prevManagedNames` set — on first
92	 * sync this will be empty so no existing headers are incorrectly stripped.
93	 * User-added headers outside that set are always preserved.
94	 */
95	function mergeHeaders(
96	  existing: { name: string; value: string }[],
97	  konnect: { name: string; value: string }[],
98	  prevManagedNames: string[],
99	): { name: string; value: string }[] {
100	  const incomingNames = new Set(konnect.map(h => h.name));
101	  const prevManaged = new Set(prevManagedNames);
102	  const userHeaders = existing.filter(h => !incomingNames.has(h.name) && !prevManaged.has(h.name));
103	  return [...konnect, ...userHeaders];
104	}
