128	 * Konnect header names are stored lowercase at the API boundary, so all comparisons are direct
129	 * string equality. `prevManagedNames` is used to detect the case where all Konnect headers were
130	 * removed from the route — incoming is empty but there are still managed headers to clean up.
131	 */
132	function konnectHeadersChanged(
133	  existing: { name: string; value: string }[],
134	  incoming: { name: string; value: string }[],
135	  prevManagedNames: string[],
136	): boolean {
137	  const prevManaged = new Set(prevManagedNames);
138	  if (incoming.length === 0) {
139	    return existing.some(h => prevManaged.has(h.name));
140	  }
141	  const incomingByName = new Map(incoming.map(h => [h.name, h.value]));
142	  let matched = 0;
143	  for (const h of existing) {
144	    const expected = incomingByName.get(h.name);
145	    if (expected !== undefined) {
146	      if (h.value !== expected) { return true; }
147	      matched++;
148	    }
149	  }
150	  return matched !== incoming.length;
151	}
