26	/**
27	 * Flush all pending timers (retries) without hardcoding delay values.
28	 *
29	 * Each retry iteration in fetchWithRetry does:
30	 *   1. setTimeout (pending timer)
31	 *   2. await the timeout → fires the callback
32	 *   3. await fetch() → microtask resolves the mock
33	 *   4. if still 429 → schedules the *next* setTimeout
34	 *
35	 * Between steps 2-4 the timer count is 0, so we can't rely on
36	 * `vi.getTimerCount()` alone. Instead we run a fixed number of
37	 * flush rounds (enough for MAX_RETRY_ATTEMPTS), yielding to
38	 * the microtask queue between each so the next timer can be
39	 * registered.
40	 */
41	async function drainRetryTimers(rounds = 10): Promise<void> {
42	  for (let i = 0; i < rounds; i++) {
43	    // Yield to let pending microtasks (mock fetch resolutions) run
44	    // and register the next setTimeout if another retry is needed.
45	    await vi.runAllTimersAsync();
46	  }
47	}
