 * - Unescapes `\/` → `/` and `\.` → `.`.
 * - Normalises an optional trailing `/?` to `/`.
 * - Named capture groups `(?<Name>...)` become `:name` (lowercased).
 * - Unnamed groups `(...)` and stray character classes `[a-z]+` become
 *   `:param_1`, `:param_2`, … sharing a single counter.
 * - Plain paths (no regex characters) are returned unchanged.
 * - If regex characters remain after substitution the function falls back:
 *   `replace` (default) → `{ path: '/:path', pathParameters: [{ name: 'path', value: '' }] }`,
 *   `keep` → `{ path: regexString, pathParameters: [] }`.
 */
export function generatePathPlaceholder(
  regexString: string,
  fallbackMode: 'keep' | 'replace' = 'replace',
): { path: string; pathParameters: NameValue[] } {
  // Plain literal path — nothing regex-like to transform.
  if (!REGEX_META.test(regexString)) {
    return { path: regexString, pathParameters: [] };
  }

  const pathParameters: NameValue[] = [];
  let working = regexString;

  // Strip anchors.
  working = working.replace(/^\^/, '').replace(/\$$/, '');

  // Normalise an optional trailing `/?` to `/`.
  working = working.replace(/\/\?$/, '/');

  // Named capture groups → :name (lowercased).
  working = working.replace(/\(\?<([A-Za-z0-9_]+)>[^)]*\)/g, (_match, name: string) => {
    const paramName = name.toLowerCase();
    pathParameters.push({ name: paramName, value: '' });
    return `:${paramName}`;
  });

  // Unnamed capture groups and stray character classes share one counter.
  let counter = 0;
  working = working.replace(/\([^)]*\)|\[[^\]]*\](?:[+*?]|\{\d+(?:,\d*)?\})?/g, () => {
    counter++;
    const paramName = `param_${counter}`;
    pathParameters.push({ name: paramName, value: '' });
    return `:${paramName}`;
  });

  // Leftover detection ignores escaped `\/` and `\.` since those become literals.
  const withoutEscaped = working.replace(/\\[/.]/g, '');
  if (REGEX_META.test(withoutEscaped)) {
    if (fallbackMode === 'keep') {
      return { path: regexString, pathParameters: [] };
    }
    return { path: '/:path', pathParameters: [{ name: 'path', value: '' }] };
  }

  // Safe to unescape now that we know no complex regex remains.
  const path = working.replace(/\\\//g, '/').replace(/\\\./g, '.');
  return { path, pathParameters };
}

/**
 * Merges Konnect-managed headers into an existing header array.
 * Konnect header names are stored lowercase at the API boundary, so all
 * comparisons here are direct string equality. Previously Konnect-managed
 * headers listed in `prevManagedNames` that are no longer incoming are
 * removed — on first sync this list is empty so no existing headers are
 * incorrectly stripped. User-added headers outside that set are preserved.
 */
export function mergeHeaders(
  existing: NameValue[],
  incoming: NameValue[],
  prevManagedNames: string[],
): NameValue[] {
  if (existing.length === 0) {
    return incoming;
  }
  const incomingNames = new Set(incoming.map(h => h.name));
  const prevManaged = new Set(prevManagedNames);
  const userHeaders = existing.filter(h => !incomingNames.has(h.name) && !prevManaged.has(h.name));
  return [...incoming, ...userHeaders];
}

/**
