 * user-filled values for params that still appear in the incoming list, drops
 * params no longer incoming, and adds new params with an empty value.
 */
export function mergePathParameters(existing: NameValue[], incoming: NameValue[]): NameValue[] {
  const existingByName = new Map(existing.map(p => [p.name, p.value]));
  return incoming.map(p => ({ name: p.name, value: existingByName.get(p.name) ?? '' }));
}

