/**
 * Resolves the URL path suffix, path parameters, and request name for an HTTP
 * route path. Kong regex paths (prefixed with `~`) are converted into
 * colon-style parameters via {@link generatePathPlaceholder}; when a regex is
 * too complex to parse it falls back to `/:path` and the request keeps its
 * original tilde-prefixed path string as the name. Plain paths are unchanged.
 */
function resolveHttpPath(
  route: { name: string | null; paths: string[] | null; id: string },
  routePath: string | null,
): { urlPath: string; pathParameters: { name: string; value: string }[]; baseName: string } {
  const isRegex = routePath !== null && routePath.startsWith('~');
  if (!isRegex) {
    return {
      urlPath: resolvePath(routePath),
      pathParameters: [],
      baseName: buildRequestName({ ...route, paths: routePath !== null ? [routePath] : null }),
    };
  }

  const resolved = resolvePath(routePath);
  const { path, pathParameters } = generatePathPlaceholder(resolved);
  // A `/:path` fallback means the regex was too complex to represent — keep the
  // original tilde-prefixed path as the name so the user can still recognise it.
  const isFallback = path === '/:path'
    && pathParameters.length === 1
    && pathParameters[0].name === 'path';
  return {
    urlPath: path,
    pathParameters,
    baseName: isFallback ? (routePath as string) : path,
  };
